#include <bits/stdc++.h>
using namespace std;

using vi = vector<int>; using vvi = vector<vi>;
using ii = pair<int,int>; using vii = vector<ii>;
using l = long long; using vl = vector<l>; using vvl = vector<vl>;
using ll = pair<l,l>; using vll = vector<ll>; using vvll = vector<vll>;
using lu = unsigned long long;
using vb = vector<bool>; using vvb = vector<vb>;
using vd = vector<double>; using vvd = vector<vd>;
const int INF = numeric_limits<int>::max();
const double EPS = 1e-10;
const l e5 = 100000, e6 = 1000000, e7 = 10000000, e9 = 1000000000;

l mod_pow(l base, l exp, l mod) {
  l result = 1;
  while (exp > 0) {
    if (exp & 1) result = (result * base) % mod;
    base = (base * base) % mod;
    exp >>= 1;
  }
  return result;
}

const l MOD_CONST = e9 + 7;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  l p, k;
  while (cin >> p >> k) {
    if (k == 0) {
      cout << mod_pow(p, p - 1, MOD_CONST) << "\n";
      continue;
    }
    if (k == 1) {
      cout << mod_pow(p, p, MOD_CONST) << "\n";
      continue;
    }
    vector<bool> visited(p, false);
    l total_cycles = 0;
    for (l i = 1; i < p; ++i) {
      if (visited[i]) continue;
      l j = i;
      l cycle_length = 0;
      while (!visited[j]) {
        visited[j] = true;
        j = (j * k) % p;
        cycle_length++;
      }
      if (mod_pow(k, cycle_length, p) == 1) total_cycles++;
    }
    cout << mod_pow(p, total_cycles, MOD_CONST) << "\n";
  }
}
